    "originalFull": "וְכֹ֣ל שִׂ֣יחַ הַשָּׂדֶ֗ה טֶ֚רֶם יִֽהְיֶ֣ה בָאָ֔רֶץ וְכָל עֵ֥שֶׂב הַשָּׂדֶ֖ה טֶ֣רֶם יִצְמָ֑ח כִּי֩ לֹ֨א הִמְטִ֜יר יְהוָ֤ה אֱלֹהִים֙ עַל הָאָ֔רֶץ וְאָדָ֣ם אַ֔יִן לַֽעֲבֹ֖ד אֶת הָֽאֲדָמָֽה׃",
    "transliterationFull": "Vekhol Siycha Hasadeh Terem Yiheyeh Va'arets Vekhal 'esev Hasadeh Terem Yitsemach Kiy Lo' Himetiyr Yehvah 'elohiym 'al Ha'arets Ve'adam 'ayin La'avod 'et Ha'adamah",
    "portuguese": "Não havia ainda nenhuma planta do campo na terra, pois ainda nenhuma erva do campo havia brotado; porque o Senhor Deus não fizera chover sobre a terra, e também não havia homem para lavrar o solo.",
